/* ===================== CANTEIRO ===================== */
const LOT = { W: 12, D: 20 };
const HOUSE = { x0: 2.5, x1: 9.5, z0: 6.5, z1: 13 };
const lot = { built: false, obj: null, data: null, cols: new THREE.Group(), dyn: new THREE.Group(), actor: null, ax: 6, az: 1.2, wp: 0, keys: {}, manual: false, acts: [{ x: 0, y: 0.8, z: 0, radius: 1.5 }] };
const WAY = [[6, 1.2], [6, 5.4], [10.8, 5.4], [10.8, 14.2], [8, 18.6], [3, 18.6], [1.2, 14.2], [1.2, 5.4], [4, 3.2], [8, 3.2]];
function buildLotStatic() {
  const g = new THREE.Group();
  const gr = new THREE.Mesh(new THREE.PlaneGeometry(90, 90), mGround2); gr.rotation.x = -Math.PI / 2; gr.position.set(6, -0.02, 9); gr.receiveShadow = true; g.add(gr);
  const yard = new THREE.Mesh(new THREE.PlaneGeometry(LOT.W, LOT.D), mGround); yard.rotation.x = -Math.PI / 2; yard.position.set(6, 0, 10); yard.receiveShadow = true; g.add(yard);
  box(90, 0.04, 4.6, mAsphalt, 6, 0.0, -4.6, g);           // rua
  box(90, 0.1, 2.2, mConcrete, 6, 0.04, -1.1, g);          // calçada
  box(1.6, 0.03, 6.6, mConcrete, 6, 0.02, 3.2, g);         // caminho até a porta
  // casa
  const hw = HOUSE.x1 - HOUSE.x0, hd = HOUSE.z1 - HOUSE.z0, hcx = (HOUSE.x0 + HOUSE.x1) / 2, hcz = (HOUSE.z0 + HOUSE.z1) / 2;
  box(hw, 2.8, hd, mHouse, hcx, 1.4, hcz, g);
  const roof = new THREE.Mesh(new THREE.ConeGeometry(1, 1.5, 4), mRoof); roof.rotation.y = Math.PI / 4;
  roof.scale.set((hw + 1.2) / Math.SQRT2, 1, (hd + 1.2) / Math.SQRT2); roof.position.set(hcx, 2.8 + 0.75, hcz); roof.castShadow = roof.receiveShadow = true; g.add(roof);
  box(1.1, 2.1, 0.08, mDoor, 6, 1.05, HOUSE.z0 - 0.04, g);
  box(1.6, 1.1, 0.08, mGlass, 3.8, 1.5, HOUSE.z0 - 0.04, g);
  box(1.6, 1.1, 0.08, mGlass, 8.2, 1.5, HOUSE.z0 - 0.04, g);
  // muros
  box(5, 1.4, 0.2, mWall, 2.5, 0.7, 0, g); box(5, 1.4, 0.2, mWall, 9.5, 0.7, 0, g);
  box(0.2, 1.8, LOT.D, mWall, 0, 0.9, 10, g); box(0.2, 1.8, LOT.D, mWall, LOT.W, 0.9, 10, g); box(LOT.W, 1.8, 0.2, mWall, 6, 0.9, LOT.D, g);
  return g;
}
const EX_HOUSE = { rect: { x: HOUSE.x0 - 0.7, z: HOUSE.z0 - 0.7, w: HOUSE.x1 - HOUSE.x0 + 1.4, d: HOUSE.z1 - HOUSE.z0 + 1.4 } };
const EX_PATH = { rect: { x: 5.1, z: 0, w: 1.8, d: HOUSE.z0 } };
const AREAS = {
  front_yard: [{ rect: { x: 0.5, z: 0.5, w: 11, d: 5.6 } }],
  backyard: [{ rect: { x: 0.5, z: 13.7, w: 11, d: 5.8 } }],
  sides: [{ rect: { x: 0.5, z: 6.2, w: 1.3, d: 7.4 } }, { rect: { x: 10.2, z: 6.2, w: 1.3, d: 7.4 } }],
  sidewalk_tree: [{ rect: { x: 0.8, z: -1.9, w: 10.4, d: 1.2 } }],
};
/* separa as espécies sorteadas pela tabela regional em regras de dispersão */
function rulesFor(ctx, seed, opt) {
  const seen = new Set(); const picks = [];
  for (let i = 0; i < 60 && picks.length < opt.n; i++) {
    const id = GVS.pickForContext(GVS.regions.br, ctx, `${seed}:${ctx}:${i}`);
    const sp = GVS.getSpecies(id);
    if (seen.has(id) || sp.archetype === 'vine') continue;   // trepadeiras precisam de um suporte
    if (opt.noLarge && (sp.size === 'l' || (sp.tags.includes('tree') && sp.size !== 's'))) continue;
    seen.add(id); picks.push(sp);
  }
  const isTree = (s) => s.tags.includes('tree') && s.size !== 's';
  const trees = picks.filter(isTree).map((s) => s.id);
  const hedges = picks.filter((s) => !isTree(s) && s.archetype === 'shrub' && s.tags.includes('hedge')).map((s) => s.id);
  const ground = picks.filter((s) => s.archetype === 'grass_tuft' || s.archetype === 'fern').map((s) => s.id);
  const mid = picks.filter((s) => !isTree(s) && !hedges.includes(s.id) && !ground.includes(s.id)).map((s) => s.id);
  const rules = [];
  if (trees.length) rules.push({ species: trees, density: opt.treeDensity || 0.03, minDistance: 4.2, scale: [0.85, 1.05], maxCount: opt.trees, prefer: 'any' });
  if (hedges.length) rules.push({ species: hedges, density: 0.5, minDistance: 1.1, prefer: 'edge', edgeWidth: 0.6, scale: [0.9, 1.1], maxCount: opt.hedges });
  if (mid.length) rules.push({ species: mid, density: 0.45, minDistance: 0.9, scale: [0.85, 1.15], maxCount: opt.mid });
  if (ground.length) rules.push({ species: ground, density: 1.2, minDistance: 0.5, scale: [0.8, 1.2], maxCount: opt.ground });
  return { rules, picks };
}
function buildLotVeg() {
  if (lot.obj) { lot.dyn.remove(lot.obj); disposeTree(lot.obj); lot.obj = null; }
  clearGroup(lot.cols);
  const seed = 'quintal-' + st.lotSeed; const all = []; const used = new Set();
  const run = (ctx, areas, opt, tag) => {
    const { rules, picks } = rulesFor(ctx, seed, opt);
    picks.forEach((p) => used.add(p.id));
    areas.forEach((a, i) => {
      const ex = [EX_HOUSE, EX_PATH, ...(opt.exclude || [])];
      const r = rules.map((x) => Object.assign({}, x, { maxCount: Math.max(1, Math.ceil(x.maxCount / areas.length)) }));
      all.push(...GV.scatter(a, r, { seed: `${seed}:${tag}:${i}`, exclude: ex }));
    });
  };
  run('front_yard', AREAS.front_yard, { n: 12, trees: 1, hedges: 10, mid: 14, ground: 40, noLarge: true }, 'f');
  run('backyard', AREAS.backyard, { n: 14, trees: 3, hedges: 4, mid: 12, ground: 50 }, 'b');
  run('front_yard', AREAS.sides, { n: 8, trees: 0, hedges: 4, mid: 6, ground: 14, noLarge: true }, 's');
  run('sidewalk_tree', AREAS.sidewalk_tree, { n: 4, trees: 2, hedges: 0, mid: 0, ground: 0, treeDensity: 0.3 }, 'c');
  const t0 = performance.now();
  const data = GV.buildLot(all, (id) => spec(id), { seed, quality: st.lotQ, lod: st.lod, condition: st.cond, season: st.season });
  lot.buildMs = performance.now() - t0; lot.data = data; lot.used = used; lot.count = all.length;
  lot.obj = GV.createLotObject(THREE, data, mats);
  lot.obj.traverse((c) => { if (c.isMesh) { c.castShadow = true; c.receiveShadow = true; } });
  lot.dyn.add(lot.obj);
  for (const c of data.colliders) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(c.r, c.r, c.h, 14, 1, true), new THREE.MeshBasicMaterial({ color: c.damage ? 0xff7a1a : 0xe5251d, wireframe: true }));
    m.position.set(c.x, c.h / 2, c.z); lot.cols.add(m);
  }
  lot.cols.visible = st.lotCol;
}
function ensureLot() {
  if (lot.built) return; lot.built = true;
  root.lot.add(buildLotStatic(), lot.dyn, lot.cols);
  lot.actor = new THREE.Mesh(new THREE.CapsuleGeometry(0.28, 1.0, 4, 10), mActor); lot.actor.castShadow = true; lot.actor.position.set(lot.ax, 0.78, lot.az);
  root.lot.add(lot.actor);
  buildLotVeg();
  camera.userData.lot = { pos: new THREE.Vector3(27, 25, 3), tgt: new THREE.Vector3(5, 0, 10) };
}
function blocked(x, z) {
  if (x < 0.55 || x > LOT.W - 0.55 || z < 0.55 || z > LOT.D - 0.55) return true;
  if (x > HOUSE.x0 - 0.4 && x < HOUSE.x1 + 0.4 && z > HOUSE.z0 - 0.4 && z < HOUSE.z1 + 0.4) return true;
  if (lot.data) for (const c of lot.data.colliders) { const dx = x - c.x, dz = z - c.z, r = c.r + 0.3; if (dx * dx + dz * dz < r * r) return true; }
  return false;
}
function stepLot(dt) {
  let dx = 0, dz = 0; const k = lot.keys;
  let ix = 0, iz = 0;
  if (k.ArrowLeft || k.a) ix -= 1; if (k.ArrowRight || k.d) ix += 1;
  if (k.ArrowUp || k.w) iz += 1; if (k.ArrowDown || k.s) iz -= 1;
  if (ix || iz) {   // relativo à câmera: frente = para onde a câmera olha
    let fx = controls.target.x - camera.position.x, fz = controls.target.z - camera.position.z; const fl = Math.hypot(fx, fz) || 1; fx /= fl; fz /= fl;
    dx = fx * iz - fz * ix; dz = fz * iz + fx * ix;
    lot.manual = true; if (st.lotAuto) { st.lotAuto = false; $('#lotAuto').checked = false; }
    const l = Math.hypot(dx, dz); dx /= l; dz /= l;
  }
  else if (st.lotAuto && !lot.manual) {
    const t = WAY[lot.wp]; const ddx = t[0] - lot.ax, ddz = t[1] - lot.az, d = Math.hypot(ddx, ddz);
    if (d < 0.25) { lot.wp = (lot.wp + 1) % WAY.length; } else { dx = ddx / d; dz = ddz / d; }
  }
  if (dx || dz) {
    const sp = (st.lotAuto && !lot.manual ? 2.0 : 3.2) * dt;
    let nx = lot.ax + dx * sp, nz = lot.az + dz * sp;
    if (!blocked(nx, lot.az)) lot.ax = nx; if (!blocked(lot.ax, nz)) lot.az = nz;
    if (st.lotAuto && !lot.manual && blocked(nx, nz)) lot.wp = (lot.wp + 1) % WAY.length;
    lot.actor.rotation.y = Math.atan2(dx, dz);
  }
  lot.actor.position.set(lot.ax, 0.78, lot.az);
  const a = lot.acts[0]; a.x = lot.ax; a.z = lot.az; a.y = 0.8; mats.setActors(lot.acts);
}
let hudT = 0;
function updateHud(now) {
  if (now - hudT < 400 || !lot.data) return; hudT = now;
  $('#hud').innerHTML =
    `<b>Canteiro 12 × 20 m</b> · semente ${st.lotSeed}<br>` +
    `Vegetação: <b>${fmt(lot.data.triangleCount, 0)}</b> triângulos · ${lot.data.plantCount} plantas<br>` +
    `Malhas de vegetação: <b>${Object.keys(lot.data.meshes).length}</b> (madeira, folhagem, flores)<br>` +
    `Colisores de tronco: <b>${lot.data.colliders.length}</b><br>` +
    `Draw calls (cena inteira): <b>${renderer.info.render.calls}</b> · triângulos desenhados: ${fmt(renderer.info.render.triangles, 0)}<br>` +
    `<span style="color:var(--muted)">Espécies: ${[...lot.used].map(nm).slice(0, 8).join(', ')}…</span>`;
}

/* ===================== VITRINE ===================== */
const show = { built: false, groups: {}, ground: null, size: [100, 100] };
function buildShow() {
  clearGroup(root.show); clearLabels('show'); show.groups = {};
  const MAXW = 40, GAP = 1.0, COLS = 2, COLW = MAXW + 12;
  const colZ = new Array(COLS).fill(0);
  for (const g of GROUPS) {
    const list = SPECIES.filter((s) => groupOf[s.id] === g.id);
    const plants = list.map((s) => ({ s, p: gen(s.id, { lod: st.lod }) }));
    const rows = []; let row = { items: [], w: 0, d: 0 };
    for (const it of plants) {
      const w = Math.max(1.5, it.p.bounds.radius * 2) + GAP;
      if (row.w + w > MAXW && row.items.length) { rows.push(row); row = { items: [], w: 0, d: 0 }; }
      row.items.push({ ...it, w }); row.w += w; row.d = Math.max(row.d, it.p.bounds.radius * 2, 1.6);
    }
    rows.push(row);
    const c = colZ.indexOf(Math.min(...colZ)), ox = c * COLW, gz0 = colZ[c]; let z = gz0 + 1.4, gx1 = 0;
    rows.forEach((r, ri) => {
      const cz = z + r.d / 2; let x = 3.4;
      const hm = human(); hm.position.set(-(ox + 0.9), 0, cz); hm.rotation.y = Math.PI / 2; root.show.add(hm);
      for (const it of r.items) {
        const o = plantObj(it.p); o.position.set(-(ox + x + it.w / 2 - GAP / 2), 0, cz); root.show.add(o);
        addLabel('show', nm(it.s.id), new THREE.Vector3(o.position.x, 0, cz - r.d / 2 - 0.2), 'sp', g.id + ri);
        x += it.w;
      }
      gx1 = Math.max(gx1, x); z += r.d + 1.8;
    });
    show.groups[g.id] = { x0: -(ox + gx1), x1: -ox, z0: gz0, z1: z };
    addLabel('show', g.nome, new THREE.Vector3(-(ox + 0.4), 0.2, gz0 + 0.3), 'gl');
    colZ[c] = z + 2.5;
  }
  const maxX = COLS * COLW - 8, zz = Math.max(...colZ);
  show.size = [maxX, zz];
  if (show.ground) { root.show.remove(show.ground); show.ground.geometry.dispose(); }
  show.ground = new THREE.Mesh(new THREE.PlaneGeometry(maxX + 60, zz + 60), mGround); show.ground.rotation.x = -Math.PI / 2;
  show.ground.position.set(-maxX / 2, -0.01, zz / 2); show.ground.receiveShadow = true; root.show.add(show.ground);
  show.built = true; show.dirty = false; lastCamKey = '';
}
function gotoGroup(id) {
  if (!show.built) buildShow();
  setMode('show', true);
  const b = id === 'all' ? { x0: -show.size[0], x1: 0, z0: 0, z1: show.size[1] } : show.groups[id];
  const w = b.x1 - b.x0, d = b.z1 - b.z0, cx = (b.x0 + b.x1) / 2, cz = (b.z0 + b.z1) / 2;
  const fitW = w / (2 * Math.tan((camera.fov * Math.PI) / 360) * camera.aspect), fitD = d / (2 * Math.tan((camera.fov * Math.PI) / 360));
  const dist = Math.max(fitW, fitD * 1.15, 14) * 1.05;
  controls.target.set(cx, id === 'all' ? 0 : 3, cz);
  if (id === 'all') camera.position.set(cx, dist * 0.95, cz - dist * 0.32); else camera.position.set(cx, dist * 0.78, cz - dist * 0.72);
  controls.maxDistance = Math.max(300, dist * 2); lastCamKey = '';
}

/* ===================== sala de testes (módulo de vegetação) ===================== */
/* A sala (GameTestRoom) é montada na primeira visita à aba, com o renderer do host: este laço chama room.update e o render só nesta aba. */
let room = null, roomRenderer = null, roomMod = null, roomErr = null;
function ensureRoom() {
  if (room || roomErr) return;
  const host = $('#roomHost');
  try {
    roomMod = window.VegetationTestModule.create({ GameVegetation: GV, GameVegetationSpecies: GVS, materials: mats });
    roomRenderer = new THREE.WebGLRenderer({ antialias: true });
    roomRenderer.setPixelRatio(Math.min(devicePixelRatio || 1, 2));
    roomRenderer.shadowMap.enabled = true; roomRenderer.shadowMap.type = THREE.PCFSoftShadowMap;
    roomRenderer.toneMapping = THREE.ACESFilmicToneMapping; roomRenderer.outputColorSpace = THREE.SRGBColorSpace;
    host.appendChild(roomRenderer.domElement);
    // a sala escuta teclas na janela inteira (e bloqueia Espaço/Tab): só vale enquanto a aba da sala estiver aberta
    const add = window.addEventListener;
    window.addEventListener = function (type, fn, opts) {
      if (type === 'keydown' || type === 'keyup') { const self = this; return add.call(this, type, function (e) { if (st.mode === 'room') return fn.call(self, e); }, opts); }
      return add.call(this, type, fn, opts);
    };
    try {
      const GTR = window.GameTestRoom;
      room = GTR.createTestRoom({ THREE, container: host, locale: 'pt-BR', catalog: GTR.demoItems('pt-BR'), renderer: roomRenderer, quality: 'medium' });
    } finally { window.addEventListener = add; }
    const rep = room.loadModule(roomMod);
    roomReport = rep;
    window.__room = room; window.__roomModule = roomMod; window.__roomReport = rep;
    new ResizeObserver(() => window.dispatchEvent(new Event('resize'))).observe(host);
  } catch (e) {
    roomErr = e; console.error(e);
    host.innerHTML = '<div style="color:#e4e8da;padding:24px;font-size:15px"><b>Não foi possível iniciar a sala de testes.</b><br>' + String(e && e.message || e) + '</div>';
  }
}
let roomReport = null;
function showRoom(on) {
  $('main').hidden = on; $('#roomWrap').hidden = !on;
  // a sala só roda com a aba aberta: fechou a aba, room.pause(); voltou, room.resume() (o laço do host só chama room.update nesta aba)
  if (on) { ensureRoom(); if (room) room.resume(); requestAnimationFrame(() => window.dispatchEvent(new Event('resize'))); }
  else if (room) room.pause();
}

/* ===================== modos ===================== */
const camState = {};
function setMode(m, silent) {
  if (m === st.mode && silent) return;
  if (m === 'room') {
    if (st.mode && st.mode !== 'room') camState[st.mode] = { p: camera.position.clone(), t: controls.target.clone() };
    st.mode = 'room'; mats.setActors([]);
    $$('.tabs button').forEach((b) => b.setAttribute('aria-selected', b.dataset.mode === 'room'));
    showRoom(true);
    if (!silent) updateHash();
    return;
  }
  const fromRoom = st.mode === 'room';
  if (fromRoom) showRoom(false); else camState[st.mode] = { p: camera.position.clone(), t: controls.target.clone() };
  st.mode = m;
  for (const k in root) root[k].visible = k === m;
  for (const k in labelItems) labelItems[k].forEach((it) => { if (k !== m) it.el.style.display = 'none'; });
  $$('.tabs button').forEach((b) => b.setAttribute('aria-selected', b.dataset.mode === m));
  $$('[data-for]').forEach((e) => { e.hidden = !e.dataset.for.split(' ').includes(m); });
  $('#common').hidden = false;
  controls.maxPolarAngle = Math.PI * 0.495; controls.minDistance = 1.2;
  if (m === 'cat') { if (!cat.plant || !camState.cat) renderCat(true); else { restoreCam('cat'); if (cat.stale) renderCat(false); } cat.stale = false; setSun(0, 0, Math.max(cat.disc.scale.x, 6) * 1.2, 2); }
  if (m === 'lot') {
    ensureLot(); if (lot.stale) { buildLotVeg(); lot.stale = false; } const first = !camState.lot; setSun(6, 9, 22, 0);
    if (first) { const c = camera.userData.lot; if (camera.aspect < 1) c.pos.sub(c.tgt).multiplyScalar(1.5 / camera.aspect ** 0.6).add(c.tgt); camera.position.copy(c.pos); controls.target.copy(c.tgt); controls.maxDistance = 70; } else restoreCam('lot');
    $('#hint').textContent = 'Arraste para girar · W A S D ou setas movem o personagem · a vegetação cede quando ele passa';
  } else mats.setActors([]);
  if (m === 'show') {
    if (!show.built || show.dirty) { buildShow(); camState.show = null; }
    setSun(-show.size[0] / 2, show.size[1] / 2, Math.max(show.size[0], show.size[1]) * 0.62, 0);
    if (!camState.show) gotoGroup('all'); else restoreCam('show');
    $('#hint').textContent = 'Todas as espécies em escala real · clique numa planta para ver no catálogo';
  }
  lastCamKey = ''; controls.update();
  if (!silent) updateHash();
}
function restoreCam(m) { const s = camState[m]; if (s) { camera.position.copy(s.p); controls.target.copy(s.t); } }
function updateHash() { try { history.replaceState(null, '', '#' + st.mode + (st.mode === 'cat' ? '/' + st.id : '')); } catch (e) { /* file:// restrito */ } }

/* ---------- controles ---------- */
function rebuildAll() {
  if (st.mode === 'cat') renderCat(false);
  else if (st.mode === 'lot') buildLotVeg();
  else if (st.mode === 'show') { buildShow(); }
  if (st.mode !== 'cat') cat.stale = true;
  if (st.mode !== 'lot' && lot.built) lot.stale = true;
  if (st.mode !== 'show') show.dirty = true;
}
let rbT = 0;
const later = (fn, ms = 120) => { clearTimeout(rbT); rbT = setTimeout(fn, ms); };
function bindControls() {
  const setSeed = (v) => { st.seed = Math.max(0, Math.min(99999, Math.round(v))); $('#seed').value = st.seed; if (st.mode === 'cat') renderCat(false); else rebuildAll(); };
  $('#seed').addEventListener('input', (e) => { if (e.target.value !== '') setSeed(+e.target.value); });
  $('#seedPrev').onclick = () => setSeed(st.seed - 1); $('#seedNext').onclick = () => setSeed(st.seed + 1);
  $('#seedRand').onclick = () => setSeed(Math.floor(Math.random() * 10000));
  const setLot = (v) => { st.lotSeed = Math.max(0, Math.min(99999, Math.round(v))); $('#lotSeed').value = st.lotSeed; buildLotVeg(); };
  $('#lotSeed').addEventListener('input', (e) => { if (e.target.value !== '') setLot(+e.target.value); });
  $('#lotPrev').onclick = () => setLot(st.lotSeed - 1); $('#lotNext').onclick = () => setLot(st.lotSeed + 1);
  $('#lotRand').onclick = () => setLot(Math.floor(Math.random() * 10000));
  $('#lod').addEventListener('click', (e) => { const b = e.target.closest('button'); if (!b) return; st.lod = +b.dataset.v; $$('#lod button').forEach((x) => x.setAttribute('aria-pressed', x === b)); rebuildAll(); });
  $('#lotQ').addEventListener('click', (e) => { const b = e.target.closest('button'); if (!b) return; st.lotQ = b.dataset.v; $$('#lotQ button').forEach((x) => x.setAttribute('aria-pressed', x === b)); buildLotVeg(); });
  $('#cond').onchange = (e) => { st.cond = e.target.value; rebuildAll(); };
  $('#season').onchange = (e) => { st.season = e.target.value; rebuildAll(); };
  const wind = () => { st.wind = +$('#wind').value; $('#windV').textContent = Math.round(st.wind * 100) + '%'; mats.setWind({ strength: st.wind, gust: st.wind * 0.5 }); };
  $('#wind').addEventListener('input', wind); wind();
  $('#lotAuto').onchange = (e) => { st.lotAuto = e.target.checked; lot.manual = !st.lotAuto; };
  $('#lotCol').onchange = (e) => { st.lotCol = e.target.checked; lot.cols.visible = st.lotCol; };
  $$('.tabs button').forEach((b) => b.addEventListener('click', () => setMode(b.dataset.mode)));
  addEventListener('keydown', (e) => {
    if (st.mode !== 'lot' || /INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)) return;
    const k = e.key.length === 1 ? e.key.toLowerCase() : e.key;
    if (['w', 'a', 's', 'd', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(k)) { lot.keys[k] = true; e.preventDefault(); }
  });
  addEventListener('keyup', (e) => { const k = e.key.length === 1 ? e.key.toLowerCase() : e.key; delete lot.keys[k]; });
  addEventListener('blur', () => { lot.keys = {}; });
  // clicar numa planta da vitrine abre no catálogo
  const ray = new THREE.Raycaster(), ndc = new THREE.Vector2(); let dn = null;
  canvas.addEventListener('pointerdown', (e) => { dn = [e.clientX, e.clientY]; });
  canvas.addEventListener('pointerup', (e) => {
    if (st.mode !== 'show' || !dn || Math.hypot(e.clientX - dn[0], e.clientY - dn[1]) > 5) return;
    const r = canvas.getBoundingClientRect(); ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
    ray.setFromCamera(ndc, camera);
    for (const h of ray.intersectObjects(root.show.children, true)) { let o = h.object; while (o && !o.userData.speciesId) o = o.parent; if (o) { selectSpecies(o.userData.speciesId); return; } }
  });
}

/* ---------- laço principal ---------- */
let stageW = 1, stageH = 1;
function resize() {
  const r = stage.getBoundingClientRect(); stageW = Math.max(1, Math.round(r.width)); stageH = Math.max(1, Math.round(r.height));
  renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 2)); renderer.setSize(stageW, stageH, false);
  camera.aspect = stageW / stageH; camera.updateProjectionMatrix(); lastCamKey = '';
}
new ResizeObserver(resize).observe(stage); addEventListener('resize', resize);
const clock = new THREE.Clock();
function frame() {
  const dt = Math.min(clock.getDelta(), 0.1), t = clock.elapsedTime;
  mats.update(t);
  if (st.mode === 'room') {
    if (room) { room.update(Math.min(dt, 0.05)); roomRenderer.render(room.scene, room.camera); }
    requestAnimationFrame(frame);
    return;
  }
  if (st.mode === 'lot') { stepLot(dt); updateHud(performance.now()); }
  controls.update();
  renderer.render(scene, camera);
  updateLabels(false);
  requestAnimationFrame(frame);
}

/* ---------- início ---------- */
buildCatalogUI(); renderList(); bindControls(); resize();
for (const k in root) root[k].visible = false;
{
  const h = (location.hash || '').replace(/^#/, '').split('/');
  const m = ['cat', 'lot', 'show', 'room'].includes(h[0]) ? h[0] : 'cat';
  if (h[1] && GVS.getSpecies(h[1])) { st.id = h[1]; renderList(); }
  st.mode = ''; setMode(m, false);
}
frame();
$('#windV').textContent = Math.round(st.wind * 100) + '%';
window.__viveiro = { st, selectSpecies, setMode, gotoGroup, lot, show, camera, controls, renderer, SPECIES, ensureRoom };
document.documentElement.dataset.ready = '1';
